<script setup>
import {ref,computed,nextTick} from 'vue'
import {useIrrigation} from '../../data/runtime.js'
import {useListState} from '../../composables/useListState.js'
import {useDraftGuard} from '../../composables/useDraftGuard.js'
import BaseModal from '../../components/BaseModal.vue'
import DataTable from '../../components/DataTable.vue'
import Pagination from '../../components/Pagination.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import MetricCard from '../../components/MetricCard.vue'
import FormField from '../../components/FormField.vue'
import {notify,confirmAction} from '../../composables/feedback.js'
import {roles,clone,columns,ordered,failureText} from '../alarms/supportUi.js'
const r=useIrrigation(),state=useListState('settings',{tab:'users'}),modal=ref(false),mode=ref(''),draft=ref({}),baseline=ref(''),reason=ref(''),busy=ref(false),failure=ref(''),errors=ref({})
const users=computed(()=>ordered(r.state.entities.User??[],state.sort)),visible=computed(()=>users.value.slice((state.page-1)*15,state.page*15)),policy=computed(()=>r.state.entities.SystemPolicy?.[0]),policyDraft=ref(policy.value?clone(policy.value):null),policyBase=ref(JSON.stringify(policyDraft.value)),policyFailure=ref(''),policyErrors=ref({})
const policyKeys={defaultStaleSec:{label:'过期阈值',unit:'s'},commandAckTimeoutSec:{label:'应答超时',unit:'s'},actionConfirmTimeoutSec:{label:'动作确认',unit:'s'},maxScheduleDays:{label:'最长编排',unit:'天'}}
const policyDirty=computed(()=>JSON.stringify(policyDraft.value)!==policyBase.value),modalDirty=computed(()=>modal.value&&(mode.value==='disable'?!!reason.value:JSON.stringify(draft.value)!==baseline.value)),guard=useDraftGuard(()=>policyDirty.value||modalDirty.value)
const cols=columns([['number','',53],['name','用户标识',150],['account','账号',170],['role','角色',193],['phone','联系电话',196],['fieldIds','田块数',95],['status','状态',155],['actions','操作',216]])
function open(user,action='edit'){mode.value=action==='disable'?'disable':action==='enable'?'enable':user?'edit':'create';draft.value=user?clone(user):{name:'',account:'',role:'VIEWER',phone:'',fieldIds:[]};baseline.value=JSON.stringify(draft.value);reason.value='';failure.value='';errors.value={};modal.value=true}
function canDisable(u){return r.can('USER_DISABLE',u)&&u.userId!==r.state.user?.userId&&!(u.role==='ADMIN'&&u.status==='ENABLED'&&users.value.filter(x=>x.role==='ADMIN'&&x.status==='ENABLED').length<=1)}
async function close(){if(busy.value)return;if(!modalDirty.value||await confirmAction({title:'放弃未保存内容',message:'账号内容尚未保存，确认放弃？',confirmText:'放弃'}))modal.value=false;else{modal.value=false;await nextTick();modal.value=true}}
async function switchTab(tab){if(tab===state.tab)return;if(policyDirty.value&&!await confirmAction({title:'放弃参数修改',message:'运行参数尚未保存，确认放弃？',confirmText:'放弃'}))return;if(policy.value){policyDraft.value=clone(policy.value);policyBase.value=JSON.stringify(policyDraft.value)}state.tab=tab;policyFailure.value='';policyErrors.value={}}
async function saveUser(){busy.value=true;failure.value='';errors.value={};try{const action={create:'USER_CREATE',edit:'USER_UPDATE',disable:'USER_DISABLE',enable:'USER_ENABLE'}[mode.value],payload=['disable','enable'].includes(mode.value)?{userId:draft.value.userId,reason:reason.value}:draft.value;await r.commit(action,payload,{expectedVersion:draft.value.version,clientRequestId:crypto.randomUUID()});notify('账号已保存');baseline.value=JSON.stringify(draft.value);reason.value='';modal.value=false;guard.markClean()}catch(e){failure.value=failureText(e);errors.value=e.fieldErrors??{}}finally{busy.value=false}}
async function savePolicy(){if(!policyDraft.value||busy.value)return;busy.value=true;policyFailure.value='';policyErrors.value={};const submitted=clone(policyDraft.value),before=JSON.parse(policyBase.value);try{const changes=Object.entries(policyKeys).map(([key,item])=>item.label+'：'+before[key]+' '+item.unit+' → '+submitted[key]+' '+item.unit).join('\n');if(!await confirmAction({title:'确认运行参数修改',message:'请核对以下参数修改：\n'+changes,confirmText:'确认保存'}))return;await r.commit('POLICY_SAVE',submitted,{expectedVersion:submitted.version,clientRequestId:crypto.randomUUID()});policyDraft.value=clone(policy.value);policyBase.value=JSON.stringify(policyDraft.value);notify('运行参数已保存');guard.markClean()}catch(e){policyFailure.value=failureText(e);policyErrors.value=e.fieldErrors??{}}finally{busy.value=false}}
function resetPolicy(){if(policy.value){policyDraft.value=clone(policy.value);policyBase.value=JSON.stringify(policyDraft.value)}policyFailure.value='';policyErrors.value={}}
</script>
<template><div class="page-stack settings-page"><section class="panel settings-main"><header class="settings-tabs"><div class="tabs"><button class="tab" :class="{active:state.tab==='users'}" @click="switchTab('users')">用户权限</button><button class="tab" :class="{active:state.tab==='policy'}" @click="switchTab('policy')">运行参数</button></div><button v-if="state.tab==='users'" class="btn btn-primary" :disabled="!r.can('USER_CREATE')" @click="open()">新增账号</button></header><template v-if="state.tab==='users'"><div class="stat-grid account-metrics"><MetricCard label="账号总数" :value="users.length" icon="user"/><MetricCard label="启用账号" :value="users.filter(u=>u.status==='ENABLED').length" icon="check"/><MetricCard label="停用账号" :value="users.filter(u=>u.status==='DISABLED').length" icon="close" tone="danger"/></div><div class="account-table"><DataTable :columns="cols" :rows="visible" row-key="userId" :sort="state.sort" compact @update:sort="state.sort=$event"><template #cell-number="{index}">{{(state.page-1)*15+index+1}}</template><template #cell-role="{value}">{{roles[value]||value}}</template><template #cell-fieldIds="{value}">{{value?.length??0}}</template><template #cell-status="{value}"><StatusBadge :status="value"/></template><template #cell-actions="{row}"><button class="btn btn-sm" :disabled="!r.can('USER_UPDATE',row)" @click="open(row)">编辑</button><button v-if="row.status==='ENABLED'" class="btn btn-sm btn-danger" :disabled="!canDisable(row)" :title="row.userId===r.state.user?.userId?'不能停用当前登录账号':'不能停用最后一名启用管理员'" @click="open(row,'disable')">停用</button><button v-else class="btn btn-sm" :disabled="!r.can('USER_ENABLE',row)" @click="open(row,'enable')">启用</button></template></DataTable><Pagination v-model="state.page" :total="users.length"/></div></template><form v-else-if="policyDraft" class="policy-form" @submit.prevent="savePolicy"><p class="muted">参数版本 V{{policyDraft.version}}</p><p v-if="policy?.version!==policyDraft.version" class="error-text">运行参数已在其他页面更新，当前草稿保留。请重置后重新编辑。</p><div class="form-grid"><FormField v-for="(item,key) in policyKeys" :key="key" :label="item.label+'（'+item.unit+'）'" :error="policyErrors[key]" required><input v-model.number="policyDraft[key]" type="number" min="1" step="1" :disabled="busy||!r.can('POLICY_SAVE',policy)"/></FormField></div><p v-if="policyFailure" role="alert" class="error-text">{{policyFailure}}</p><table v-if="policyDirty" class="policy-diff"><caption>参数修改核对</caption><thead><tr><th>运行参数</th><th>修改前</th><th>修改后</th></tr></thead><tbody><tr v-for="(item,key) in policyKeys" :key="key"><th>{{item.label}}</th><td>{{JSON.parse(policyBase)[key]}} {{item.unit}}</td><td>{{policyDraft[key]}} {{item.unit}}</td></tr></tbody></table><div class="form-actions"><button type="button" class="btn" :disabled="busy" @click="switchTab('users')">取消编辑</button><button type="button" class="btn" :disabled="busy" @click="resetPolicy">重置</button><button class="btn btn-primary" :disabled="busy||!policyDirty||!r.can('POLICY_SAVE',policy)">保存参数</button></div></form><p v-else class="empty-state">未找到运行参数，请重新进入此页面。</p></section><section class="panel policy-summary"><h2 class="panel-title">系统参数摘要</h2><div v-if="policy" class="stat-grid"><div v-for="(item,key) in policyKeys" :key="key" class="policy-metric"><span>{{item.label}}</span><strong>{{policy[key]}} <small>{{item.unit}}</small></strong></div></div><p v-else class="empty-state">暂无运行参数</p></section><BaseModal :model-value="modal" :title="{create:'新增账号',edit:'编辑账号',disable:'停用账号',enable:'启用账号'}[mode]" :busy="busy" width="700px" @update:model-value="close"><template v-if="mode==='disable'||mode==='enable'"><p>确认{{mode==='disable'?'停用':'启用'}} {{draft.name}}（{{draft.account}}）？</p><FormField v-if="mode==='disable'" label="停用原因（至少6字）" :error="errors.reason" required><textarea v-model="reason" rows="3" :disabled="busy"/></FormField></template><template v-else><div class="form-grid"><FormField label="用户标识" :error="errors.name" required><input v-model="draft.name" :disabled="busy"/></FormField><FormField label="账号" :error="errors.account" required><input v-model="draft.account" :disabled="busy" autocomplete="off"/></FormField><FormField label="角色" :error="errors.role" required><select v-model="draft.role" :disabled="busy"><option v-for="(label,key) in roles" :key="key" :value="key">{{label}}</option></select></FormField><FormField label="联系电话" :error="errors.phone" required><input v-model="draft.phone" :disabled="busy" inputmode="tel" maxlength="11"/></FormField></div><FormField label="田块授权范围" :error="errors.fieldIds"><div class="field-authorizations"><label v-for="f in r.state.entities.Field" :key="f.fieldId"><input v-model="draft.fieldIds" type="checkbox" :value="f.fieldId" :disabled="busy"/>{{f.name}}</label></div></FormField></template><p v-if="failure" class="error-text" role="alert">{{failure}}</p><template #footer><button class="btn" :disabled="busy" @click="close">取消</button><button class="btn btn-primary" :disabled="busy" @click="saveUser">确认{{mode==='disable'?'停用':mode==='enable'?'启用':'保存'}}</button></template></BaseModal></div></template>
<style scoped>.settings-page{gap:14px;margin:1px 0}.settings-main{overflow:hidden;padding:0}.settings-tabs{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e0e8e3;height:55px;padding:0 20px 0 26px}.settings-tabs .tabs{border:0;height:100%;gap:30px}.settings-tabs .tab{padding:15px 0 10px;font-size:17px}.settings-tabs>.btn{height:36px}.account-metrics{grid-template-columns:repeat(3,1fr);gap:13px;margin:13px 15px 14px}.account-metrics :deep(.metric-card){height:84px;min-height:0;padding:13px 17px;gap:22px}.account-metrics :deep(.metric-icon){border-radius:50%}.account-metrics :deep(.metric-number){font-size:29px}.account-table{margin:0 15px 0}.account-table :deep(td){height:33px;padding-top:2px;padding-bottom:2px;font-size:14px}.account-table :deep(th){height:38px;font-size:14px}.account-table :deep(.btn-sm){height:26px;min-height:26px;padding:1px 16px;margin-right:14px;font-size:13px}.account-table :deep(.pagination){min-height:58px}.policy-summary{padding:12px 17px}.policy-summary .panel-title{font-size:17px;margin-bottom:10px}.policy-summary .stat-grid{gap:12px}.policy-metric{border:1px solid #e1e8e4;border-radius:5px;height:84px;padding:10px 22px;display:flex;flex-direction:column;gap:6px}.policy-metric span{color:#617a71;font-size:14px}.policy-metric strong{font-size:28px;line-height:1.25}.policy-metric small{font-size:20px;font-weight:500}.policy-form{padding:25px;min-height:520px}.policy-diff{width:100%;border-collapse:collapse;margin-top:22px;font-size:14px}.policy-diff caption{text-align:left;margin-bottom:8px;font-weight:600}.policy-diff th,.policy-diff td{padding:9px 13px;border:1px solid #e1e8e4;text-align:left}.policy-diff thead{background:#f0f7f3}.policy-form .form-grid{margin-top:25px;gap:30px}.field-authorizations{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:8px}.field-authorizations label{display:flex;gap:7px;align-items:center;font-size:14px}.field-authorizations input{min-height:0;width:16px;height:16px}
</style>
